declare(strict_types=1);require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/helpers.php';
function z($t,$a,$b,$c,$d,$k){$o=[$a,$b,$c,$d];return[$t,$o,$k,$o[ord($k)-97]];}function save_agri($n,$qs){$db=db();$l=query_one("SELECT l.id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Agriculture and Food Technology' AND l.medium='Sinhala' AND l.display_order=? AND l.status='active' LIMIT 1",'i',[$n]);if(!$l)throw new RuntimeException("Lesson $n missing");$q=query_one("SELECT id FROM quizzes WHERE lesson_id=? AND status='active' LIMIT 1",'i',[$l['id']]);$id=(int)($q['id']??0);if(!$id)throw new RuntimeException("Quiz $n missing");$db->query("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=$id AND qq.activity_type='challenge'");$db->query("DELETE FROM quiz_questions WHERE quiz_id=$id AND activity_type='challenge'");$s=$db->prepare("INSERT INTO quiz_questions(quiz_id,activity_type,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,'challenge',?,?,?,?,?,?,?,?,'active')");foreach($qs as $i=>$v){[$t,$o,$k,$e]=$v;$p=$i+1;$s->bind_param('isssssssi',$id,$t,$o[0],$o[1],$o[2],$o[3],$k,$e,$p);$s->execute();}$db->query("UPDATE quizzes SET title_si='$n වන පාඩම — MCQ ප්‍රශ්න 30',timer_minutes=30,pass_mark=50 WHERE id=$id");$c=(int)query_one("SELECT COUNT(*) n FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge' AND status='active'",'i',[$id])['n'];if($c!==30)throw new RuntimeException("Lesson $n has $c");}
